document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".booking-list"),t=document.getElementById("total-rows"),n=document.getElementById("total-sum");if(!e||!t||!n)return;const o={1:5,2:7,3:7,4:5,5:7,6:7,7:4,8:3,9:3,10:4,11:7};function c(){let c=0,a=0;e.querySelectorAll('input[type="checkbox"]').forEach(e=>{if(!e.checked)return;const t=function(e){const t=parseInt(e.value,10);return o[t]||0}(e);e.closest("label").classList.contains("checkT--table-1")?c+=t:a+=t});const l=1400*c,r=1250*a;t.innerHTML="",c&&s(c,1400,l),a&&s(a,1250,r),n.textContent=`${l+r} ₽`}function s(e,n,o){const c=document.createElement("div");c.className="booking-total__row",c.innerHTML=`<span>${e}шт | ${n}р</span><span>${o}р</span>`,t.appendChild(c)}e.addEventListener("change",c),c()});